// WF-2 guard — validate state per 02 §3
const state = $input.first().json;
if (!state || state.schema_version !== 1) throw new Error(`WF-2 live: invalid schema_version ${JSON.stringify(state?.schema_version)}`);
state.loop = state.loop || { gate: "test", remaining: 3 };
state.candidate = state.candidate || null;
state.test = state.test || { passed: false, runs: [] };
// pass through mutation_constraints and objections as context for synthesis
return [{ json: state }];

// WF-2 prompt builder — assembles Lab system prompt + goal + mutation constraints + previous stderr
const state = $input.first().json;
const promptFile = '/prompts/lab_synthesis_live.md';
// In n8n, prompts are mounted at /prompts; Code Node can read via fs if allowed, else we embed a fallback
let systemPrompt = '';
try {
  systemPrompt = require('fs').readFileSync(promptFile, 'utf8');
} catch (e) {
  systemPrompt = `You are the Code Synthesis Agent. Output ONLY JSON {tool_name, description, input_schema, code}.`;
}
let ctx = systemPrompt + "\n\n";
ctx += `Goal: ${state.goal}\n\n`;
if (state.recall && state.recall.mutation_constraints && state.recall.mutation_constraints.length) {
  ctx += "Mutation constraints (obey):\n" + state.recall.mutation_constraints.map(c => `- ${c}`).join("\n") + "\n\n";
}
if (state.audit && state.audit.objections && state.audit.objections.length) {
  ctx += "Audit objections to fix (previous candidate rejected):\n" + state.audit.objections.map(o => `- [${o.severity}] ${o.detail}`).join("\n") + "\n\n";
}
if (state.test && state.test.runs && state.test.runs.length) {
  const last = state.test.runs[state.test.runs.length-1];
  ctx += `Previous test failed (loop remaining ${state.loop.remaining}):\nstderr: ${(last.stderr||'').slice(0,800)}\nstdout: ${(last.stdout||'').slice(0,500)}\nFix the code and return a corrected candidate.\n\n`;
}
ctx += "Return ONLY JSON.";
return [{ json: { state, llm_prompt: ctx } }];

// WF-2 parse LLM JSON → state.candidate
const llmResp = $input.first().json;
const prev = $('Build LLM prompt').first().json.state;
let raw = llmResp.response || llmResp.body?.response || JSON.stringify(llmResp);
if (typeof raw !== 'string') raw = JSON.stringify(raw);
let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  const lines = cleaned.split('\n');
  if (lines[0].startsWith('```')) lines.shift();
  if (lines[lines.length-1].startsWith('```')) lines.pop();
  cleaned = lines.join('\n').trim();
}
let cand;
try {
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  const js = cleaned.slice(start, end+1);
  cand = JSON.parse(js);
} catch (e) {
  // Repair retry: emit a candidate with the parse error as description so the loop can capture it
  throw new Error(`WF-2 JSON parse failed: ${e.message} — raw: ${cleaned.slice(0,800)}`);
}
if (!cand.tool_name || !cand.code) throw new Error(`WF-2 candidate missing tool_name/code: ${JSON.stringify(cand).slice(0,500)}`);
cand.language = cand.language || 'python';
const next = JSON.parse(JSON.stringify(prev));
next.candidate = cand;
return [{ json: next }];

// WF-2 loop bookkeeping — test failed, decrement remaining
const state = $input.first().json;
const next = JSON.parse(JSON.stringify(state));
next.loop.remaining = (next.loop.remaining || 3) - 1;
if (next.loop.remaining < 0) next.loop.remaining = 0;
// If exhausted, mark outcome failed for Orchestrator to log to problem_store
if (next.loop.remaining === 0) {
  next.outcome = next.outcome || {};
  next.outcome.status = 'failed';
  next.outcome.final_answer = `Lab exhausted after test failures. Last stderr: ${(next.test.runs[next.test.runs.length-1]?.stderr||'').slice(0,500)}`;
}
return [{ json: next }];
